def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # Find a diagonal pair of identical non-background cells and extend their line.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1), (-1, -1), (-1, 1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Continue beyond the second point, filling only background cells.
                rr, cc = r2 + dr, c2 + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] == bg:
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
                return out
    return out

